\draw[black,line width=0.4pt] (5,0)--(5,-15);
\draw[black,line width=0.4pt] (10,0)--(10,-15);
\draw[black,line width=0.4pt] (15,0)--(15,-15);
\draw[black,line width=0.4pt] (20,0)--(20,-15);
\draw[black,line width=0.4pt] (25,0)--(25,-15);
\draw[black,line width=0.4pt] (0,-5)--(30,-5);
\draw[black,line width=0.4pt] (0,-10)--(30,-10);
\draw[black,line width=0.8pt] (0,0) rectangle (30,-15);
\end{tikzpicture}[/tikz]
